#' Plot an INTERACT VisNetwork Graph for a Single Sample
#'
#' @description Takes an `igraph` object generated by `BuildGraph()`
#' and renders an interactive HTML widget using `visNetwork`.
#'
#' @param graph A directed `igraph` object generated by `BuildGraph()`.
#' @param top.n Optional integer. Number of top population-level edges to display.
#' If NULL (default), all edges in the graph object are shown.
#'
#' @return A `visNetwork` htmlwidget object.
#'
#' @importFrom dplyr %>%
#' @importFrom igraph V E as_data_frame subgraph.edges
#' @importFrom tibble as_tibble tibble
#' @importFrom ggsci pal_igv
#' @importFrom visNetwork visNetwork visPhysics visEdges visOptions visInteraction
#' @export
PlotVisNetwork = function(graph, top.n = NULL) {

  if (is.null(graph)) {
    message("Invalid graph object. No interactions to visualize.")
    return(NULL)
  }

  # Extract sample ID directly from graph attributes (fallback to "Sample" if missing)
  sample.id = ifelse(is.null(graph$sample.id), "Sample", graph$sample.id)

  # 1. Prune Graph (top.n) ----

  plot.graph = graph

  if (!is.null(top.n)) {
    edge.weights = igraph::E(plot.graph)$weight
    if (length(edge.weights) > top.n) {
      # Identify the weight threshold for the top N edges
      threshold = sort(edge.weights, decreasing = TRUE)[top.n]
      # Subset the graph to only include these top edges
      plot.graph = igraph::subgraph.edges(
        plot.graph,
        which(edge.weights >= threshold),
        delete.vertices = TRUE
      )
    }
  }

  # 2. Setup Aesthetics ----

  all.cell.types = igraph::V(plot.graph)$name
  color.palette = ggsci::pal_igv()(length(all.cell.types))
  names(color.palette) = all.cell.types

  # 3. Extract and Format Edges/Nodes ----

  edges = tibble::as_tibble(igraph::as_data_frame(plot.graph, what = "edges")) %>%
    dplyr::mutate(
      title = paste0("<b>Sender:</b> ", from, "<br><b>Receiver:</b> ", to,
                     "<br><b>Total Interaction Weight:</b> ", round(weight, 2),
                     "<br><b>L-R Pairs:</b> ", n.pairs, "<hr>", top.interactions),
      value = weight
    )

  nodes = tibble::tibble(id = igraph::V(plot.graph)$name, label = igraph::V(plot.graph)$name) %>%
    dplyr::mutate(
      color = color.palette[id],
      # Utilize the boolean attribute set in the builder function to enlarge the tumor
      size = ifelse(igraph::V(plot.graph)$is.tumor, 45, 25),
      shadow = TRUE,
      title = paste0("<b>Cell Type:</b> ", id, "<br>",
                     "<b>Signals Sent:</b> ", igraph::V(plot.graph)$sent.count, "<br>",
                     "<b>Signals Received:</b> ", igraph::V(plot.graph)$received.count, "<hr>",
                     igraph::V(plot.graph)$genomic.info)
    )

  # 4. Render visNetwork HTML Widget ----

  visNetwork::visNetwork(nodes, edges, main = paste("Multi-Layer Signaling Ecosystem:", sample.id)) %>%
    visNetwork::visPhysics(solver = "forceAtlas2Based", stabilization = TRUE) %>%
    visNetwork::visEdges(
      arrows = "to",
      color = list(color = "gray80", highlight = "#0072B2"),
      smooth = TRUE
    ) %>%
    visNetwork::visOptions(
      highlightNearest = list(enabled = TRUE, hover = TRUE, degree = 1),
      nodesIdSelection = TRUE
    ) %>%
    visNetwork::visInteraction(hover = TRUE, tooltipDelay = 100)
}
